<?php
declare(strict_types=1);ob_start();require dirname(__DIR__).'/portal-private/bootstrap.php';$p=getenv('PORTAL_CONFIG_FILE');if(!$p||!str_ends_with($p,'config.test.php'))throw new RuntimeException('Solo pruebas.');$c=require$p;if(!str_ends_with($c['db_name'],'_test'))throw new RuntimeException('Solo base de pruebas.');$app=portal_app();$db=$app->db();$n=0;
function actor(string$u):void{global$db;$s=$db->prepare('SELECT id,auth_version FROM pisco_users WHERE username=?');$s->execute([$u]);$r=$s->fetch();$_SESSION['user_id']=(int)$r['id'];$_SESSION['auth_version']=(int)$r['auth_version'];}
function ok(bool$v,string$l):void{global$n;if(!$v)throw new RuntimeException($l);$n++;echo"OK $l\n";}
function change(callable$f):array{global$app;$b=$app->bootstrap();$d=$b['data'];$f($d);return$app->save(['data'=>$d,'revision'=>$b['revision']]);}
function reject(int$s,callable$f,string$l):void{try{$f();}catch(PortalError$e){ok($e->status===$s,$l);return;}throw new RuntimeException($l);}
actor('admin');$full=$app->bootstrap()['data'];$code='DEEP-DOC-'.strtoupper(bin2hex(random_bytes(6)));
try{actor('70001001');change(function(&$d)use($code){$d['academico']['docs'][]=['cod'=>$code,'tipo'=>'cert','ref'=>1001,'persona'=>'Nombre inventado','fecha'=>'2001-01-01','por'=>'Emisor inventado','valido'=>false];});$d=$app->bootstrap()['data'];$issued=PortalPolicy::find($d['academico']['docs'],'cod',$code);ok($issued['persona']==='Alumno de prueba 1001','El titular de la constancia viene del maestro de alumnos');ok(str_starts_with($issued['fecha'],date('Y-m-d'))&&$issued['por']===$app->user()['nombre'],'Fecha y emisor se fijan en PHP');ok($issued['valido']===true,'La nueva emisión usa el estado autorizado por el servidor');
reject(403,fn()=>change(function(&$d){$d['academico']['docs'][]=['cod'=>'DEEP-OTHER-12345678','tipo'=>'cert','ref'=>1002,'persona'=>'Otra persona','fecha'=>date(DATE_ATOM),'valido'=>true];}),'Alumno no emite documentos de otro alumno');
reject(403,fn()=>change(function(&$d)use($code){foreach($d['academico']['docs']as&$r)if($r['cod']===$code)$r['valido']=false;}),'Alumno no modifica una constancia ya emitida');
actor('admin');reject(422,fn()=>change(function(&$d){$d['academico']['certs']=array_values(array_filter($d['academico']['certs'],fn($r)=>$r['id']!==9001));}),'No se retira la certificación mientras tiene constancias vigentes');change(function(&$d){foreach($d['academico']['docs']as&$r)if($r['tipo']==='cert'&&$r['ref']===1001)$r['valido']=false;});$result=$app->lookup('certificados',['reference'=>$code]);ok($result['record']['estado']==='Anulado','Revocación administrativa visible en la verificación pública');change(function(&$d){$d['academico']['certs']=array_values(array_filter($d['academico']['certs'],fn($r)=>$r['id']!==9001));});ok(!PortalPolicy::find($app->bootstrap()['data']['academico']['certs'],'id',9001),'Una fuente retirada después de anular sus constancias se conserva como retirada');
}finally{actor('admin');$app->save(['data'=>$full,'revision'=>$app->bootstrap()['revision']]);}
echo"\n$n comprobaciones de emisión, titularidad y revocación aprobadas.\n";ob_end_flush();
